update employee
set username = #{username}, name = #{name}, gender = #{gender}, phone = #{phone}, position = #{position}, salary = #{salary}, avatar = #{avatar}, entry_date = #{entryDate}, department_id = #{departmentId}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select , department.name departmentName
from employee left join department on employee.department_id = department.id


         employee.name like concat('%', #{name}, '%')



         and employee.gender = #{gender}




         and employee.entry_date between #{begin} and #{end}


 order by employee.update_time desc, employee.id desc
